#!/usr/bin/env python3
"""File newly discovered utterances into the episode files on main."""
import subprocess, re, json, os, sys

REPO = "/tmp/wt-main-edit"

def git(*a):
    return subprocess.run(["git", "-C", REPO] + list(a), capture_output=True, text=True).stdout

FRIENDS = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]

def collect():
    msgs = []
    for f in FRIENDS:
        out = git("log", "--format=%H%x1f%cI", "origin/friend/" + f)
        for line in out.splitlines():
            if not line.strip():
                continue
            sha, ts = line.split("\x1f")
            body = git("show", "--format=%B", "-s", sha)
            if not re.search(r"^Friend-Message:\s*1\s*$", body, re.M):
                continue
            m = re.search(r"^Episode:\s*(\S+)\s*$", body, re.M)
            if not m:
                continue
            ep = m.group(1)
            sp = re.search(r"^Speaker:\s*(.+?)\s*$", body, re.M)
            r = re.search(r"^Reply-To:\s*(\S+)\s*$", body, re.M)
            lines = body.split("\n")
            ri = [i for i, l in enumerate(lines) if l.startswith("Reply-To:")][0]
            j = ri + 1
            while j < len(lines) and lines[j].strip() == "":
                j += 1
            ut = "\n".join(lines[j:]).strip()
            msgs.append(dict(branch=f, sha=sha, ts=ts, ep=ep, reply=r.group(1) if r else None,
                             speaker=sp.group(1) if sp else f, ut=ut))
    return msgs

def filed_map():
    filed = {}
    for path in git("ls-tree", "-r", "--name-only", "HEAD").splitlines():
        if re.match(r"S\d+/E\d+\.md$", path):
            c = git("show", "HEAD:" + path)
            for b, s in re.findall(r"^Source: friend/(\w+) @ ([0-9a-f]{40})", c, re.M):
                filed.setdefault(path, set()).add((b, s))
    return filed

def entry(m):
    return (f"**{m['speaker']}** ({m['ts']})\n\n"
            f"Source: friend/{m['branch']} @ {m['sha']}\n\n"
            f"{m['ut']}\n")

def main():
    msgs = collect()
    filed = filed_map()
    plan = {}
    for m in msgs:
        path = m["ep"] + ".md"
        key = (m["branch"], m["sha"])
        if path in filed and key in filed[path]:
            continue
        # skip word-for-word republications of an already filed utterance
        if path in filed:
            body = git("show", "HEAD:" + path)
            if m["ut"] and m["ut"] in body:
                print("SKIP duplicate text:", path, m["branch"], m["sha"][:10])
                continue
        plan.setdefault(path, []).append(m)
    for path, lst in sorted(plan.items()):
        lst.sort(key=lambda m: (m["ts"], m["sha"]))
        print("FILE", path, len(lst), "utterances")
        for m in lst:
            print("   ", m["ts"], m["speaker"], m["sha"][:10])
    json.dump({k: v for k, v in plan.items()}, open("/tmp/plan.json", "w"), indent=1)

main()
